    storesB4: 'Merch & Board ລາຍຈາກສະກຸນ',
    affiliateB1Desc: 'ແຕ່ລະບັນຊີມີລິ້ງອ້າງອີງແລະລະຫັດທີ່ເປັນເອກະລັກທີ່ທ່ານສາມາດແບ່ງປັນໄດ້ທຸກບ່ອນ, ລວມທັງ/r/ລິ້ງສັ້ນ. ລິ້ງອ້າງອີງສາມາດຊີ້ໄປທີ່ ຫນ້າ ໃດ ຫນຶ່ງ ໃນ DeHub, ຫນ້າ ເຊີນສາມາດສະ ເຫນີ ຈຸດ ຫມາຍ ປາຍທາງຫຼາຍຢ່າງ, ແລະບົດຂຽນ blog ທີ່ທ່ານແບ່ງປັນຖືລິ້ງຂອງທ່ານໂດຍອັດຕະໂນມັດ.',
    affiliateB3Desc: 'Dashboard Affiliate ສະແດງການກົດປຸ່ມ, ການລົງທະບຽນແລະລາຍໄດ້ຂອງທ່ານ, ແລະອະນຸຍາດໃຫ້ທ່ານປັບແຕ່ງຫນ້າການເຊື້ອເຊີນຂອງທ່ານແລະຮູບພາບການແບ່ງປັນຂອງມັນ. ການຢ້ຽມຢາມຂອງນາງແມ່ນບໍ່ ຈໍາ ເປັນ.',
    aiSuiteB3Desc: 'ອະທິບາຍແອັບພລິເຄຊັນໃນພາສາ ທໍາ ມະດາໃຫ້ @ ຜູ້ຊ່ວຍໃນຂໍ້ຄວາມຂອງທ່ານແລະມັນກໍ່ສ້າງມັນ, ຫຼັງຈາກນັ້ນໃຫ້ທ່ານມີລິ້ງການເບິ່ງລ່ວງ ຫນ້າ ທີ່ສາມາດແບ່ງປັນໄດ້. dehub.io/builder ເລີ່ມຕົ້ນການສົນທະນາ ສໍາ ລັບທ່ານ.',
    aiSuiteCreditsDesc: 'Generation ແມ່ນຈ່າຍໃນ DeHub tokens. ເຄື່ອງແມ່ຂ່າຍໄດ້ກ່າວເຖິງລາຄາຂອງວຽກກ່ອນທີ່ຈະດໍາເນີນການ, ທ່ານອະນຸມັດການໂອນເງິນດຽວ, ແລະວຽກເລີ່ມຕົ້ນເມື່ອການຈ່າຍເງິນໄດ້ຮັບການຢືນຢັນໃນຕ່ອງໂສ້. ແຕ່ລະກະເປົາເງິນໄດ້ຮັບ 5 ຮູບພາບໂດຍບໍ່ເສຍຄ່າໃນຮູບແບບທີ່ມີລາຄາຖືກທີ່ສຸດເພື່ອທົດລອງໃຊ້, ແລະຄວາມສົມດຸນຂອງເຄື່ອງ ຫມາຍ ທີ່ມີມູນຄ່າໂດລາໃນ ຫນ້າ ຜູ້ສ້າງຂອງທ່ານສາມາດຈ່າຍຄ່າວຽກໄດ້ໂດຍບໍ່ຕ້ອງເຊັນກະເປົາເງິນທຸກຄັ້ງ. ການ dubbing ຂັ້ນຕອນແມ່ນຄິດໄລ່ໃນວິທີການດຽວກັນ, ໂດຍນາທີ.',
    adsPortalDesc: 'ທຸລະກິດສາມາດ ດໍາ ເນີນການໂຄສະນາໃນ DeHub ຜ່ານປະຕູໂຄສະນາທີ່ ກໍາ ຫນົດເອງ — ສ້າງແຄມເປນ, top up with DeHub tokens, ແລະຕິດຕາມການປະຕິບັດ, ດ້ວຍການໂຄສະນາທີ່ໃຫ້ບໍລິການພື້ນເມືອງເຂົ້າໃນອາຫານ. ໃນ ຫນ້າ ໂພສ ຄໍາ ເຫັນຈະມາກ່ອນການໂຄສະນາໃດໆ, ແລະຜູ້ອ່ານສາມາດຂໍເບິ່ງໂຄສະນາ ຫນ້ອຍ ລົງ.',
    notificationsB1Desc: 'ຄວາມມັກຕາມປະເພດໃນການຕັ້ງຄ່າ ກໍາ ນົດສິ່ງທີ່ຖືກສົ່ງໄປທັງ ຫມົດ, ສະນັ້ນທ່ານສາມາດຮັກສາ ຄໍາ ແນະ ນໍາ ແລະຫຼຸດຜ່ອນການຕອບສະ ຫນອງ. ແຕະຖືກຈັດອັນດັບຕາມກິດຈະ ກໍາ, ແຕ່ລະອັນສະແດງໃຫ້ເຫັນ ຈໍາ ນວນທີ່ບໍ່ໄດ້ອ່ານຂອງຕົນເອງ, ແລະທ່ານສາມາດເລືອກເຂົ້າໃນການແຈ້ງເຕືອນການສົນທະນາສາທາລະນະດ້ວຍຂໍ້ ຈໍາ ກັດກ່ຽວກັບ ຈໍາ ນວນທີ່ມາຮອດຕໍ່ຊົ່ວໂມງ.',
    notificationsB6: 'ເຄື່ອງໝາຍ:',
    tocKids: 'ໂໝດເດັກນ້ອຍ',
    kidsTitle: 'ໂໝດເດັກນ້ອຍ',
