    converterB1Desc: 'YouTube, SoundCloud, Instagram ກັບຄວາມອອກອອກນີ້, ບາງບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມາດບັນປະກອບສາມ',
