    ourServiceText2: 'DeHub ດຳເນີນການເປັນໂປຣໂຕຄອລແບບກະຈາຍ.',
    softwareDevelopers: 'ໃຜເປັນຜູ້ດຳເນີນງານ DeHub',
    softwareDevText1: 'DeHub ແມ່ນ DAO ອິດສະຫຼະ. ບໍ່ມີບໍລິສັດໃດເປັນເຈົ້າຂອງ ດຳເນີນງານ ຫຼື ຄວບຄຸມການບໍລິການນີ້. ໂປຣໂຕຄອນ ແພລດຟອມ ແລະ ຄັງຊັບສິນ ຖືກປົກຄອງເທິງເຊນໂດຍຜູ້ຖື DeHub ຜ່ານໂປຣໂຕຄອນທຳມາພິບານຂອງ DeHub ເຊິ່ງເປີດໃຊ້ງານແລ້ວ: ຂໍ້ສະເໜີຖືກຍື່ນ ແລະ ລົງຄະແນນສຽງພາຍໃນແອັບ ແລະ ຜົນລັບຜູກມັດທັງລະບົບນິເວດ. ໃນຂໍ້ຕົກລົງນີ້ "DeHub" "ພວກເຮົາ" ແລະ "ຂອງພວກເຮົາ" ໝາຍເຖິງ DAO ແລະ ໂປຣໂຕຄອນທີ່ມັນປົກຄອງ, ບໍ່ແມ່ນບໍລິສັດ.',
    softwareDevText2: 'ການພັດທະນາດຳເນີນໂດຍຜູ້ປະກອບສ່ວນ ແລະ ສະຕູດິໂອອິດສະຫຼະທີ່ DAO ຈ້າງ. ບໍ່ມີຜູ້ໃດເປັນເຈົ້າຂອງລະບົບນິເວດ DeHub ຫຼື ມີອຳນາດຕັດສິນໃຈເໜືອມັນ ແລະ ຜູ້ໃດກໍຕາມສາມາດຖືກປ່ຽນ ຫຼື ຖອດອອກໄດ້ດ້ວຍການລົງຄະແນນທຳມາພິບານ. ບໍ່ມີໃຜສາມາດປ່ຽນແປງໂປຣໂຕຄອນ ໂທເຄນ ຫຼື ຂໍ້ກຳນົດເຫຼົ່ານີ້ນອກຂະບວນການດັ່ງກ່າວ.',
