    decentralizedModerationItem4: 'ນະໂຍບາຍແມ່ນຖືກ ກໍາ ນົດໂດຍການປົກຄອງແທນທີ່ຈະເປັນອົງກອນດຽວ; ການປະຕິບັດນະໂຍບາຍດັ່ງກ່າວແມ່ນຖືກມອບໃຫ້ແກ່ຜູ້ຊີ້ ນໍາທີ່ຖືກແຕ່ງຕັ້ງທີ່ກະ ທໍາ ຢ່າງໄວວາ.',
    decentralizedModerationText: 'ການຄຸ້ມຄອງເນື້ອຫາໃນ DeHub ແມ່ນຖືກຈັດການໂດຍຜ່ານກົນໄກການປົກຄອງຊຸມຊົນ:',
    designatedModerators: 'ຜູ້ຈັດການທີ່ຖືກແຕ່ງຕັ້ງ',
    designatedModeratorsItem1: 'ຜູ້ດັດແປງທີ່ຖືກ ກໍາ ນົດອາດຈະເອົາໂພສ, ຄໍາ ເຫັນ, ກະແສຫລືລາຍການສື່ມວນຊົນໃດໆອອກທັນທີ',
    designatedModeratorsItem2: 'ຜູ້ດັດແກ້ທີ່ຖືກແຕ່ງຕັ້ງອາດຈະໂຈະ, ຈໍາກັດຫຼືລົບລ້າງບັນຊີທີ່ລະເມີດຢ່າງຖາວອນທັນທີ',
    designatedModeratorsItem3: 'ບົດລາຍງານທີ່ສົ່ງໂດຍຜູ້ໃຊ້ຖືກນຳສົ່ງໄປຫາຜູ້ດຳເນີນການທີ່ກຳນົດໄວ້ເພື່ອທົບທວນ',
    designatedModeratorsItem4: 'ການປົກຄອງ ກຳນົດນະໂຍບາຍທີ່ຜູ້ດຳເນີນການບັງຄັບໃຊ້ ແລະ ສາມາດທົບທວນ ຫຼື ປະຕິເສດການຕັດສິນໃຈຂອງພວກເຂົາ, ແຕ່ການບັງຄັບໃຊ້ເອງແມ່ນທັນທີ',
    fiatOnRampNote: 'ທ່ານເຫັນດີທີ່ຈະປະຕິບັດຕາມກົດ ຫມາຍ ແລະລະບຽບການທີ່ກ່ຽວຂ້ອງທັງ ຫມົດ ກ່ຽວກັບການຊື້ຊັບສິນດິຈິຕອນໃນເຂດປົກຄອງຂອງທ່ານ.',
    licenseToDeHub: 'ໃບອະນຸຍາດ DeHub',
    licenseToDeHubText: 'ໂດຍການສະ ຫນອງ ເນື້ອຫາໃຫ້ແກ່ບໍລິການ, ທ່ານໃຫ້ DeHub ມີໃບອະນຸຍາດທົ່ວໂລກ, ບໍ່ສະເພາະ, ບໍ່ເສຍຄ່າ royalties ເພື່ອເປັນເຈົ້າພາບແລະແຈກຢາຍເນື້ອຫາຂອງທ່ານຜ່ານເວທີ decentralized ສໍາ ລັບການ ດໍາ ເນີນງານຂອງບໍລິການ.',
    limitationText: 'ໃນຖານະເປັນເວທີ decentralized, ຄວາມຮັບຜິດຊອບຂອງ DeHub ແມ່ນຈໍາກັດຕໍ່ການປະຕິບັດເຕັກນິກຂອງໂປໂຕໂກລ. ແລະ ພວກ ເຮົາ ບໍ່ ມີ ຄວາມ ຮັບຜິດຊອບ ຕໍ່:',
    monetizationItem1: 'ການປະຕິບັດຕາມກົດ ຫມາຍ ໃນເຂດ ອໍາ ນາດທີ່ ນໍາ ໃຊ້',
    monetizationItem2: 'ການຕັດສິນໃຈກ່ຽວກັບການປົກຄອງຊຸມຊົນທີ່ເຮັດໂດຍຜ່ານການລົງຄະແນນສຽງທີ່ໂປ່ງໃສ',
    monetizationPrinciple: 'ຫຼັກການຫຼັກ: ທຸກຄົນສາມາດສ້າງລາຍໄດ້ຈາກເນື້ອຫາຂອງພວກເຂົາໄດ້ໂດຍບໍ່ມີການກວດກາສູນກາງ.',
