    notAllowed: 'ທ່ານ ບໍ່ ໄດ້ ຮັບ ອະ ນຸ ຍາດ ໃຫ້:',
    notAllowedItem1: 'ໃຊ້ບໍລິການເພື່ອແຈກຢາຍເນື້ອຫາທີ່ຜິດກົດຫມາຍພາຍໃຕ້ກົດ ຫມາຍ ທີ່ໃຊ້ໄດ້',
    notAllowedItem2: 'ການປິດລ້ອມ, ການປິດລ້ອມ ຫຼື ການລົບກວນຄຸນລັກສະນະທີ່ກ່ຽວຂ້ອງກັບຄວາມປອດໄພຂອງບໍລິການ',
