    notAllowedItem4: 'ລວບລວມຂໍ້ມູນສ່ວນຕົວໂດຍບໍ່ມີການຍິນຍອມ',
    notAllowedItem5: 'ໃຊ້ບໍລິການເພື່ອແຈກຢາຍ spam ຫຼືການຮ້ອງຂໍມະຫາຊົນທີ່ບໍ່ຕ້ອງການ',
    notAllowedItem7: 'ການລາຍງານທີ່ບໍ່ຖືກຕ້ອງ, ການທຸງ, ຫຼືຂັ້ນຕອນການປົກຄອງ',
    permissionsRestrictions: 'ການອະນຸຍາດ ແລະ ຂໍ້ຈໍາກັດ',
    restrictionsByDeHub: 'ຂໍ້ ຈໍາ ກັດໂດຍ DeHub',
    restrictionsByDeHubText: 'ການເຂົ້າເຖິງບໍລິການສາມາດຖືກ ຈໍາ ກັດໃນເວລາໃດກໍ່ຕາມ. ຂໍ້ ຈໍາ ກັດອາດຈະເກີດຂື້ນ ສໍາ ລັບ:',
    restrictionsItem3: 'ໄພຂົ່ມຂູ່ດ້ານຄວາມປອດໄພດ້ານວິຊາການຕໍ່ເວທີ',
