    contactNote: 'ການປະຕິບາຍຂອງນັງຈະມີຄວາມຕົກລົງໃນຄວາມຕົກລົງຂອງກົມມຸນທີ່ມີຄວາມຕົກລົງຂອງສັນຍານທີ່ມີຄວາມຕົກລົງຂອງສາກົນທີ່ຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລົງຂອງນັງຈະມີຄວາມຕົກລ',
    contactUpdates: 'ຕິດຕໍ່ & ອັບເດດ',
    contentModeration: 'ການດຸ່ນດ່ຽງເນື້ອຫາ & ການປົກຄອງ',
    corePrinciple: 'ຫຼັກການຫຼັກ: ພວກເຮົາເກັບກໍາບັນຊີທີ່ ຈໍາ ເປັນຢ່າງ ຫນ້ອຍ ເພື່ອເຮັດວຽກ, ພວກເຮົາບໍ່ເຄີຍຂາຍມັນ, ແລະທຸກສິ່ງທຸກຢ່າງທີ່ຜ່ານໄປທີ່ຍັງຄົງຢູ່ໃນອຸປະກອນຂອງທ່ານຫຼືຕ່ອງໂສ້ສາທາລະນະ.',
    dataSovereigntyItem2: 'ຂໍ້ຄວາມໂດຍກົງຂອງທ່ານຖືກເຂົ້າລະຫັດຈາກຕອນທ້າຍໄປຫາຕອນທ້າຍ, ສະນັ້ນບໍ່ມີໃຜໃນ DeHub ສາມາດອ່ານໄດ້',
    doCollectItem5: 'ບັນທຶກການຈ່າຍເງິນ ສໍາ ລັບສິ່ງໃດທີ່ທ່ານຊື້, ບໍ່ວ່າຈະເປັນການຕັ້ງຖິ່ນຖານຜ່ານ Stripe ຫຼືໃນຕ່ອງໂສ້, ຖືກເກັບໄວ້ ສໍາ ລັບການບັນຊີແລະການຂັດແຍ່ງ. ເລກບັດແມ່ນຖືກຈັດການໂດຍ Stripe ແລະບໍ່ເຄີຍບັນລຸພວກເຮົາ.',
    dontCollectItem1: 'ເອກະສານຕົວຕົນ — ບໍ່ມີ KYC ເພື່ອໃຊ້ DeHub',
    dontCollectItem3: 'ການທ່ອງເວັບຂອງທ່ານຢູ່ນອກ DeHub, ຫຼືການຕິດຕາມຂ້າມເວັບໄຊໃດ ຫນຶ່ງ',
    dontCollectItem4: 'ຂໍ້ມູນສະຖານທີ່ທີ່ແນ່ນອນ',
    dontCollectItem5: 'ຕົວລະບຸການໂຄສະນາ ຫຼື ລາຍລັກອັກສອນລາຍນິ້ວມືຂອງບຸກຄົນທີສາມ',
    governanceItem1: 'ການລົງຄະແນນສຽງຂອງຊຸມຊົນ ກໍາ ນົດນະໂຍບາຍເນື້ອຫາ',
    importantNotice: 'ແຈ້ງການສຳຄັນ',
    importantNoticeText: 'DeHub ເຮັດວຽກເປັນໂປໂຕໂກລ decentralized. ໃນຂະນະທີ່ພວກເຮົາພະຍາຍາມປົກປ້ອງຄວາມເປັນສ່ວນຕົວຂອງຜູ້ໃຊ້ ທໍາ ມະຊາດ decentralized ຫມາຍ ຄວາມວ່າການພົວພັນສາມາດເຫັນໄດ້ໃນ blockchain ສາທາລະນະ ຜູ້ໃຊ້ແມ່ນມີຄວາມຮັບຜິດຊອບໃນການເຂົ້າໃຈຜົນກະທົບຂອງຄວາມເປັນສ່ວນຕົວຂອງການໂຕ້ຕອບ blockchain ຂອງພວກເຂົາ.',
    legalCompliance: 'ຄວາມສອດຄ່ອງທາງກົດໝາຍ:',
    legalComplianceItem1: 'ເນື້ອຫາທີ່ຜິດກົດ ຫມາຍ ຕາມທີ່ ກໍາ ນົດໂດຍກົດ ຫມາຍ ທີ່ໃຊ້ໄດ້',
    legalComplianceText: 'ການປຽບທຽບເນື້ອຫາສາມາດເກີດຂື້ນພຽງແຕ່ ສໍາ ລັບ:',
