    notAllowedItem3: 'ການ ກະ ຕຸ້ນ ໃຫ້ ມີ ຄວາມ ຮຸນ ແຮງ, ການ ຂົ່ມ ຂູ່ ຕໍ່ ຄວາມ ຮຸນ ແຮງ, ຫຼື ການ ສັນ ລະ ເສີນ ລັດ ທິ ຫົວ ຮຸນ ແຮງ ແລະ ການ ກໍ່ ການ ຮ້າຍ',
    notAllowedItem4: 'ການຂົ່ມເຫັງ, ການຂົ່ມເຫັງແລະການລ່ວງລະເມີດເປົ້າຫມາຍ, ລວມທັງ pile-ons ທີ່ປະສານງານ',
    notAllowedItem5: 'ການເວົ້າຄວາມກຽດຊັງ, ລວມທັງການໂຈມຕີປະຊາຊົນໂດຍອີງໃສ່ເຊື້ອຊາດ, ເຊື້ອຊາດ, ຊາດກໍາເນີດ, ສາສະຫນາ, ຄວາມພິການ, ພະຍາດ, ເພດ, ຄວາມເປັນເອກະລັກທາງເພດຫຼືແນວທາງເພດ',
    notAllowedItem6: 'Doxxing ຫຼືເຜີຍແຜ່ຂໍ້ມູນສ່ວນຕົວຂອງຄົນອື່ນໂດຍບໍ່ມີການອະນຸມັດຂອງພວກເຂົາ',
    notAllowedItem8: 'ການສະແດງຕົວຂອງຄົນອື່ນ, ຜູ້ສ້າງ, ຍີ່ຫໍ້ຫຼືໂຄງການ',
    notAllowedText: 'ເນື້ອຫາແລະພຶດຕິ ກໍາ ຕໍ່ໄປນີ້ຖືກຫ້າມທຸກບ່ອນໃນ DeHub, ລວມທັງໂພສ, ຄໍາ ເຫັນ, ກະແສ, ຂໍ້ຄວາມ, ໂປຼໄຟລ໌ແລະຊື່ຜູ້ໃຊ້:',
    reportingItem1: 'ການໂພສ, ຄຳຄິດເຫັນ, ກະແສ ຫຼື ຂໍ້ຄວາມໃດໆກໍ່ສາມາດຖືກລາຍງານໂດຍໃຊ້ຕົວເລືອກລາຍງານໃນລາຍການ',
    reportingItem2: 'ທ່ານສາມາດບລັອກບັນຊີອື່ນເພື່ອຢຸດການໂຕ້ຕອບທັງ ຫມົດ ກັບມັນ',
    reportingItem3: 'ທ່ານສາມາດປິດບັນຊີເພື່ອລຶບມັນອອກຈາກອາຫານຂອງທ່ານໂດຍບໍ່ຕ້ອງກີດຂວາງມັນ',
