    whatHappensNextText: 'ລາຍງານດັ່ງກ່າວຈະຖືກທົບທວນຄືນໂດຍຜູ້ປຶກສາທີ່ຖືກແຕ່ງຕັ້ງ — ຜູ້ບໍລິຫານທີ່ຖືກເລືອກຕັ້ງໂດຍຊຸມຊົນແລະຜູ້ຖືປ້າຍຊັ້ນສູງ — ທີ່ມີອໍານາດທີ່ຖືກມອບໃຫ້ປະຕິບັດໂດຍບໍ່ຕ້ອງລໍຖ້າການລົງຄະແນນສຽງກ່ຽວກັບການປົກຄອງ.',
